import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            s = next(iterator)
            c = next(iterator)
        except StopIteration:
            break

        found = False
        n = len(s)
        for i in range(0, n, 2):
            if s[i] == c:
                found = True
                break

        if found:
            results.append("YES")
        else:
            results.append("NO")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
